import { node, textBlocks } from "./dom.js";
import {
  sourceReader,
  follow,
  highlightSource,
  clampedText,
} from "./source.js";
import { runRow } from "./run-fields.js";
/** @typedef {Record<string,any>} Wire */

/** @param {HTMLElement} root @param {Wire} dashboard */
export function inbox(root, dashboard) {
  const url = new URL(location.href),
    session = url.searchParams.get("session_id");
  const partition = url.searchParams.get("view") ?? "messages";
  const connection = dashboard.runtime().instance;
  let closed = false,
    restored = false,
    anchor = /** @type {Wire|null} */ (null),
    origin = /** @type {Wire|null} */ (null);
  const rows = node("div"),
    controls = node("div");
  rows.className = "inbox-rows";
  const preview = node("section");
  preview.setAttribute(
    "aria-label",
    session === null ? "会话列表" : "会话只读预览",
  );
  root.append(preview);
  const seen = new Set();
  const heading = node("h2", session === null ? "最近会话" : `会话 ${session}`);
  preview.append(heading);
  const actions = node("div");
  actions.className = "inbox-actions";
  const createButton = node("button", "新建会话并打开主对话");
  const createReason = node("p"),
    continueReason = node("p"),
    restoreNotice = node("p");
  for (const status of [createReason, continueReason, restoreNotice])
    status.setAttribute("role", "status");
  const continueButton = node("button", "继续此会话");
  let targetVerified = false,
    targetFailure = "",
    actionFailure = "";
  function paintActions() {
    const createState = dashboard.sessionActionState("create");
    createButton.disabled = !createState.allowed;
    createReason.textContent = createState.reason || actionFailure;
    if (session !== null) {
      const state = dashboard.sessionActionState("continue", session);
      const reason =
        state.reason ||
        (dashboard.runtime().instance !== connection
          ? "来源进程已变化，请重新核验会话。"
          : !targetVerified
            ? targetFailure || "正在核验会话身份，请等待读取。"
            : "");
      continueButton.disabled = !!reason;
      continueReason.textContent = reason;
    }
  }
  createButton.addEventListener("click", async () => {
    actionFailure = "";
    const result = await dashboard.createSession();
    if (closed) return;
    actionFailure = result.status === "applied" ? "" : result.reason;
    paintActions();
  });
  actions.append(createButton, createReason);
  preview.append(actions, restoreNotice);
  const back = node("a", "返回会话列表");
  back.href = "/inbox";
  if (session !== null) {
    follow(
      back,
      () =>
        void dashboard.navigate("/inbox", {
          source: origin || {
            route: "/inbox",
            kind: "sessions",
            anchor: session,
            trigger: {
              key: "open-session",
              href:
                "/inbox?" +
                new URLSearchParams({ session_id: session, view: "messages" }),
            },
            process_instance_id: connection,
          },
        }),
    );
    continueButton.addEventListener("click", async () => {
      const result = await dashboard.continueSession(session);
      if (closed) return;
      paintActions();
      if (result.status !== "applied")
        continueReason.textContent = result.reason;
    });
    preview.append(
      back,
      node("p", "只读预览；继续此会话将切换主对话。"),
      continueButton,
      continueReason,
    );
    const nav = node("nav");
    nav.setAttribute("aria-label", "会话预览分区");
    for (const [value, label] of [
      ["messages", "消息"],
      ["runs", "运行"],
    ]) {
      const link = node("a", label);
      link.href =
        "/inbox?" + new URLSearchParams({ session_id: session, view: value });
      if (value === partition) link.setAttribute("aria-current", "page");
      follow(
        link,
        () =>
          void dashboard.navigate(link.href, {
            source: { returnSource: origin },
          }),
      );
      nav.append(link);
    }
    preview.append(nav);
  }
  if (session !== null && !["messages", "runs"].includes(partition)) {
    targetFailure = "无效的会话预览分区。";
    const stopActions = dashboard.subscribeSessionActions(paintActions);
    preview.append(node("p", "无效的会话预览分区。"));
    return {
      close() {
        closed = true;
        stopActions();
      },
    };
  }
  preview.append(rows, controls);
  const kind =
    session === null
      ? "sessions"
      : partition === "messages"
        ? "messages"
        : "session-runs";
  const path =
    session === null
      ? "/api/sessions"
      : partition === "messages"
        ? "/api/sessions/messages"
        : "/api/sessions/runs";
  const params =
    session === null
      ? { limit: "25" }
      : partition === "messages"
        ? { session_id: session, page_size: "25" }
        : { session_id: session, limit: "25" };
  const label =
    session === null
      ? "会话"
      : partition === "messages"
        ? "会话消息"
        : "会话运行";
  /** SourceContext contains identifiers and presentation state only. */
  function captureSource() {
    return {
      route: url.pathname + url.search,
      kind,
      session_id: session,
      partition,
      anchor: anchor?.id ?? null,
      anchorKind: anchor?.kind ?? null,
      trigger: anchor?.trigger ?? null,
      process_instance_id: connection,
      observed_at: reader.observed,
      returnSource: origin,
    };
  }
  /** @param {HTMLAnchorElement} link @param {string} id @param {string} key */
  function open(link, id, key) {
    link.dataset.sourceTrigger =
      key === "session" ? "open-session" : "open-run";
    follow(link, () => {
      anchor = {
        id,
        kind: key,
        trigger: {
          key: link.dataset.sourceTrigger,
          href: link.getAttribute("href"),
        },
      };
      void dashboard.navigate(link.href, {
        source: { returnSource: captureSource() },
      });
    });
  }
  const reader = sourceReader(
    controls,
    path,
    params,
    (body, replace) => {
      const items =
        session === null
          ? [
              ...(body.non_terminal ? [body.non_terminal] : []),
              ...body.sessions,
            ]
          : partition === "messages"
            ? body.messages
            : body.runs;
      if (
        !Array.isArray(items) ||
        items.some(
          (item) =>
            typeof (session === null
              ? item.session_id
              : partition === "messages"
                ? item.message_anchor
                : item.run_id) !== "string",
        )
      )
        throw new Error("source_identity_missing");
      if (replace) {
        rows.replaceChildren();
        seen.clear();
      }
      if (typeof body.title === "string") heading.textContent = body.title;
      for (const item of items) {
        const id =
          session === null
            ? item.session_id
            : partition === "messages"
              ? item.message_anchor
              : item.run_id;
        if (seen.has(id)) continue;
        seen.add(id);
        let row = node("article");
        row.className = "card";
        row.dataset.sourceKey =
          session === null
            ? "session"
            : partition === "messages"
              ? "message"
              : "run";
        row.dataset.sourceId = id;
        if (session === null) {
          const link = node("a", item.title || "未命名会话");
          link.href =
            "/inbox?" +
            new URLSearchParams({
              session_id: item.session_id,
              view: "messages",
            });
          open(link, id, "session");
          row.append(
            link,
            node("p", item.session_id),
            node("p", item.created_at),
          );
        } else if (partition === "messages") {
          row.append(
            node("p", `${item.role} · ${item.source} · ${item.created_at}`),
          );
          clampedText(row, textBlocks(item.blocks), id);
          if (typeof item.run_id === "string") {
            const link = node("a", "查看运行");
            link.href =
              "/runs/" + encodeURIComponent(item.run_id) + "?filter=chat";
            open(link, id, "message");
            row.append(link);
          } else row.append(node("small", "历史消息 · 无 Run 关联"));
        } else {
          row = runRow(item);
          if (typeof item.reply_preview === "string")
            clampedText(row, item.reply_preview, "reply-" + item.run_id);
          const link = node("a", "查看运行");
          link.href =
            "/runs/" + encodeURIComponent(item.run_id) + "?filter=chat";
          open(link, id, "run");
          row.append(link);
        }
        rows.append(row);
      }
      if (!seen.size && !body.runs_pending)
        rows.append(
          node(
            "p",
            session === null
              ? "还没有会话，可使用页头的新建会话入口。"
              : "此分区暂无已读记录。",
          ),
        );
      if (
        body.target &&
        body.target.placement !== "waiting" &&
        body.source_focus_allowed
      )
        queueMicrotask(() => {
          if (!closed) {
            const focused = highlightSource(
              rows,
              body.target.anchor,
              session === null
                ? "session"
                : partition === "messages"
                  ? "message"
                  : "run",
              anchor?.trigger || null,
              heading,
            );
            restoreNotice.textContent = focused
              ? "已重新核验来源并恢复原入口。"
              : "原入口已不可用，已恢复列表标题。";
          }
        });
    },
    label,
    dashboard.runtime,
    () => {
      targetVerified = true;
      targetFailure = "";
      paintActions();
      reconcileWaiting(dashboard.runtime());
    },
    (code) => {
      if (code === "unknown_session") {
        targetVerified = false;
        targetFailure = "此会话不存在或不可用，请返回会话列表。";
      } else if (!targetVerified)
        targetFailure = "会话身份尚未核验，请重试读取。";
      paintActions();
    },
  );
  let creationRevision = dashboard.sessionActionState("create").createdRevision;
  const stopActions = dashboard.subscribeSessionActions(() => {
    paintActions();
    const next = dashboard.sessionActionState("create").createdRevision;
    if (next > creationRevision && session === null)
      reader.changed("有新数据，请刷新会话。");
    creationRevision = next;
  });
  let lastRevision = dashboard.runtime().revision,
    lastActive = dashboard.runtime().active;
  /** Keep historical membership and cursors fixed; only announce related
   * durable-window changes observed through the accepted Host revisions.
   * @param {Wire} state */
  function observeChanges(state) {
    if (
      state.instance !== connection ||
      state.connected !== true ||
      !Number.isSafeInteger(state.revision)
    )
      return;
    if (state.revision > lastRevision) {
      const next = state.active;
      const related = (/** @type {Wire|null} */ run) =>
        typeof run?.session_id === "string" &&
        (session === null || run.session_id === session);
      const signature = (/** @type {Wire|null} */ run) =>
        run
          ? JSON.stringify([
              run.run_id,
              run.session_id,
              run.phase,
              run.recording_state,
            ])
          : "";
      const changed = signature(next) !== signature(lastActive);
      const settled =
        (related(next) &&
          ["recorded", "failed"].includes(next.recording_state)) ||
        (related(lastActive) && next?.run_id !== lastActive.run_id);
      // Absolute replacements may skip the active slot entirely. That revision
      // cannot prove this read unchanged, so offer a conservative explicit check.
      const unlocatedChange = !lastActive && !next && lastRevision >= 0;
      if (
        (changed &&
          (session === null
            ? related(next) || related(lastActive)
            : settled)) ||
        unlocatedChange
      )
        reader.changed(
          partition === "runs" && session !== null
            ? "有新运行，请刷新会话运行。"
            : "有新数据，请刷新" + label + "。",
        );
      lastRevision = state.revision;
      lastActive = next;
    }
  }
  /** A newer synchronized Host state can release this Session's waiting
   * boundary without reading or replacing its retained cursor.
   * @param {Wire} state */
  function reconcileWaiting(state) {
    if (
      session === null ||
      partition !== "messages" ||
      state.instance !== connection ||
      state.connected !== true
    )
      return;
    const active = state.active;
    if (
      active === null ||
      (active &&
        (active.session_id !== session ||
          ["recorded", "failed"].includes(active.recording_state)))
    )
      reader.releaseWaiting(state.revision);
  }
  let lastInstance = dashboard.runtime().instance,
    lastGap = 0;
  const unsubscribe = dashboard.subscribeState((/** @type {Wire} */ state) => {
    if (state.instance && state.instance !== lastInstance) {
      lastInstance = state.instance;
      reader.invalidate("进程已变化，请重新打开此页面");
    }
    if (state.connected === false) reader.invalidate("连接中断，保留旧快照");
    if (state.readGapRevision > lastGap) {
      lastGap = state.readGapRevision;
      reader.invalidate("增量通知缺口，快照待刷新");
    }
    observeChanges(state);
    reconcileWaiting(state);
    reader.sync();
  });
  queueMicrotask(() => {
    if (!closed && !restored) void reader.load();
  });
  return {
    captureSource,
    restoreSource(/** @type {Wire} */ source) {
      origin = source?.returnSource || null;
      if (source?.kind !== kind || typeof source.anchor !== "string") return;
      restored = true;
      anchor = {
        id: source.anchor,
        kind: source.anchorKind,
        trigger: source.trigger || null,
      };
      if (source.process_instance_id !== dashboard.runtime().instance) {
        reader.invalidate("来源进程已变化；请明确刷新当前列表");
        return;
      }
      const locate =
        session === null
          ? {
              path: "/api/sessions/locate",
              params: { session_id: source.anchor, limit: "25" },
            }
          : partition === "messages"
            ? {
                path: "/api/sessions/messages/locate",
                params: {
                  session_id: session,
                  anchor: source.anchor,
                  page_size: "25",
                },
              }
            : {
                path: "/api/sessions/runs/locate",
                params: {
                  session_id: session,
                  run_id: source.anchor,
                  limit: "25",
                },
              };
      void reader.load(true, locate);
    },
    close() {
      closed = true;
      reader.close();
      unsubscribe();
      stopActions();
    },
  };
}

main-inbox-runs.css.content:
.run-source,
.inbox-rows,
[aria-label="运行摘要"] {
  container-type: inline-size;
  min-width: 0;
}
.run-row {
  border: 1px solid var(--row-divider);
  border-radius: var(--radius-panel);
  margin-block: 12px;
  padding: 14px;
  min-width: 0;
  overflow-wrap: anywhere;
}
.run-fields {
  display: grid;
  gap: 12px;
  margin: 0 0 12px;
  grid-template-columns: minmax(0, 1fr);
}
.run-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-block: 12px;
}
.inbox-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-block: 12px;
}
.inbox-actions [role="status"] {
  flex-basis: 100%;
  margin: 0;
}
.inbox-actions [role="status"]:empty {
  display: none;
}
.run-fields > div {
  min-width: 0;
}
.run-fields dt {
  font-size: var(--font-size-meta);
  font-family: var(--font-mono);
  color: var(--metadata);
}
.run-fields dd {
  margin: 4px 0 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.run-table {
  display: block;
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.run-table thead {
  display: none;
}
.run-table tbody,
.run-table tr,
.run-table td {
  display: block;
  min-width: 0;
}
.run-table tr {
  border: 1px solid var(--row-divider);
  border-radius: var(--radius-console);
  padding: 12px;
  margin-block: 12px;
}
.run-table td {
  padding: 6px;
  overflow-wrap: anywhere;
  white-space: normal;
}
.run-table dl {
  margin: 0;
}
.run-table dt {
  font-size: var(--font-size-meta);
  font-family: var(--font-mono);
  color: var(--metadata);
}
.run-table dd {
  margin: 2px 0 7px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.run-preview {
  line-height: 1.5;
  max-height: 3em;
  overflow: hidden;
}
.run-preview.expanded {
  max-height: none;
}
@container (min-width:680px) {
  .run-fields {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .run-table {
    display: table;
  }
  .run-table thead {
    display: table-header-group;
  }
  .run-table tbody {
    display: table-row-group;
  }
  .run-table tr {
    display: table-row;
  }
  .run-table td,
  .run-table th {
    display: table-cell;
    vertical-align: top;
    border-bottom: 1px solid var(--row-divider);
    padding: 8px 6px;
  }
  .run-table th {
    font-size: var(--font-size-table-header);
    font-family: var(--font-mono);
    text-align: left;
  }
  .run-table th:first-child {
    width: 20%;
  }
  .run-table th:nth-child(2) {
    width: 19%;
  }
}
[data-source-highlighted="true"] {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
.evidence-text {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  max-width: 100%;
  line-height: 1.5;
  max-height: 9em;
  overflow: hidden;
  margin-block: 10px;
}
.evidence-text.expanded {
  max-height: none;
}
[aria-label="会话预览分区"] {
  display: flex;
  gap: 20px;
  margin-block: 16px;
}
[aria-label="会话预览分区"] [aria-current="page"] {
  font-weight: 700;
  text-decoration-thickness: 3px;
}
[aria-label="运行过程"] pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-width: 100%;
}

/* V05: all additions are scoped to the Run page; Inbox keeps its renderer. */
.runs-page {
  --run-line: calc(var(--gap-small) / 12);
  --run-body-y: calc(var(--gap-large) + var(--run-line));
  --run-body-x: calc(var(--gap-large) + var(--run-line) * 3);
}
.runs-page .run-table thead {
  display: none;
}
.runs-page .run-table tbody {
  display: block;
}
.runs-page .run-table .run-list-row {
  display: flex;
  align-items: baseline;
  border: 0;
  border-bottom: var(--run-line) solid var(--row-divider);
  border-radius: 0;
  margin: 0;
  padding: calc(var(--gap-small) - var(--run-line)) var(--gap-large);
}
.runs-page .run-table .run-list-row:last-child {
  border-bottom: 0;
}
.runs-page .run-table td {
  display: block;
  border: 0;
  padding: 0;
}
.runs-page .run-list-row:hover {
  background: var(--hover);
}
.runs-page .run-list-preview {
  color: var(--secondary);
}
.runs-page .run-list-preview dd {
  font-size: var(--font-size-row);
}
.runs-page .run-list-meta,
.runs-page .run-list-identity {
  margin-block: calc(var(--gap-small) / 2);
}
.runs-page .run-list-meta > div,
.runs-page .run-list-identity > div {
  display: flex;
  flex-wrap: wrap;
  gap: calc(var(--gap-small) / 3);
  min-width: 0;
}
.runs-page .run-list-meta dd,
.runs-page .run-list-identity dd {
  margin: 0;
  color: var(--tertiary);
}
.runs-page .run-list-context {
  color: var(--metadata);
  font: 400 var(--font-size-meta)/1.5 var(--font-mono);
}
.runs-page .run-list-context dl {
  display: grid;
  gap: var(--gap-small);
  margin-block: var(--gap-small);
  grid-template-columns: repeat(auto-fit, minmax(min(100%, calc(var(--gap-large) * 10)), 1fr));
}
.runs-page .run-list-context dd {
  color: var(--tertiary);
}
.runs-page .run-list-actions {
  font: 400 var(--font-size-meta)/1.5 var(--font-mono);
}
.runs-page .run-summary {
  border: 0;
  border-radius: 0;
  margin: 0;
  padding: var(--run-body-y) var(--run-body-x);
}
.runs-page .run-summary-lead {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--gap-large);
  margin-bottom: var(--gap-medium);
}
.runs-page .run-summary-message {
  flex: 1 1 calc(var(--gap-large) * 15);
  min-width: 0;
  margin: 0;
}
.runs-page .run-summary-meta {
  flex: 1 1 calc(var(--gap-large) * 15);
  min-width: 0;
}
.runs-page .run-summary dt {
  color: var(--metadata);
  font: 400 var(--font-size-meta)/1.5 var(--font-mono);
}
.runs-page .run-summary dd {
  margin: calc(var(--gap-small) / 3) 0 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.runs-page .run-summary-meta dd {
  color: var(--tertiary);
}
.runs-page .run-summary-costs {
  color: var(--attention);
}
.runs-page .run-read-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--gap-small);
  min-width: 0;
  font: 400 var(--font-size-meta)/1.5 var(--font-mono);
  color: var(--metadata);
}
.runs-page .run-read-controls p {
  margin: 0;
  flex: 1 1 calc(var(--gap-large) * 12);
}
.runs-page .run-summary-panel .run-read-controls {
  justify-content: flex-end;
}
.runs-page > .run-read-status {
  margin-block: var(--gap-small);
  color: var(--metadata);
  font: 400 var(--font-size-meta)/1.5 var(--font-mono);
}
.runs-page > [role="status"]:empty {
  display: none;
}
.runs-page .run-process-body > p,
.runs-page .run-process-body > a {
  margin: var(--gap-small) var(--run-body-x);
}
.runs-page .run-step {
  border-bottom: var(--run-line) solid var(--panel-divider);
}
.runs-page .run-step:last-child {
  border-bottom: 0;
}
.runs-page .run-step-heading {
  align-items: baseline;
}
.runs-page .run-step-number {
  margin: 0;
  font: 600 var(--font-size-meta)/1.5 var(--font-mono);
  color: var(--accent);
}
.runs-page .run-step-outcome {
  margin: 0;
  color: var(--tertiary);
  font-family: var(--font-mono);
}
.runs-page .attempt,
.runs-page .input-preparation {
  padding: 0;
  border: 0;
  border-top: var(--run-line) solid var(--row-divider);
  min-width: 0;
}
.runs-page .attempt.aborted {
  background: var(--raised);
  border-left: var(--run-line) dashed var(--attention);
}
.runs-page .attempt.aborted > summary {
  text-decoration: none;
}
.runs-page .attempt.aborted .run-attempt-label {
  color: var(--attention);
  text-decoration: line-through;
}
.runs-page .run-attempt-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--gap-small);
  padding: calc(var(--gap-small) - var(--run-line)) var(--run-body-x);
  color: var(--tertiary);
  font: 400 var(--font-size-row)/1.5 var(--font-mono);
  cursor: pointer;
}
.runs-page .run-attempt-heading::before {
  content: "▸";
  color: var(--faint);
}
.runs-page details[open] > .run-attempt-heading::before {
  content: "▾";
}
.runs-page .run-attempt-label {
  flex: 1 1 calc(var(--gap-large) * 12);
  min-width: 0;
}
.runs-page .run-duration {
  margin-left: auto;
}
.runs-page .run-cost {
  font: 400 var(--font-size-meta)/1.5 var(--font-mono);
}
.runs-page .run-inputs,
.runs-page .run-aggregation,
.runs-page .run-routing,
.runs-page .run-graph,
.runs-page .run-usage,
.runs-page .run-export {
  margin-block: var(--gap-medium);
}
.runs-page .run-graph {
  padding: var(--run-body-y) var(--run-body-x);
}
.runs-page .run-summary-identity {
  margin-bottom: var(--gap-small);
}
.runs-page .run-summary-identity > div {
  min-width: 0;
}
.runs-page .run-summary-context {
  color: var(--metadata);
  font: 400 var(--font-size-meta)/1.5 var(--font-mono);
}
.runs-page .run-summary-context .run-fields {
  margin-top: var(--gap-small);
  color: var(--secondary);
}
.runs-page .run-list-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-small);
}
.runs-page .run-list-title {
  margin: 0;
  font: inherit;
  color: inherit;
}
.runs-page .run-preview:not(.expanded) {
  white-space: nowrap;
  text-overflow: ellipsis;
  max-height: none;
}

before-inbox.js.content:
import { node, textBlocks } from "./dom.js";
import {
  sourceReader,
  follow,
  highlightSource,
  clampedText,
} from "./source.js";
import { runRow } from "./run-fields.js";
/** @typedef {Record<string,any>} Wire */

/** @param {HTMLElement} root @param {Wire} dashboard */
export function inbox(root, dashboard) {
  root.classList.add("inbox-page");
  const url = new URL(location.href),
    session = url.searchParams.get("session_id");
  const partition = url.searchParams.get("view") ?? "messages";
  const connection = dashboard.runtime().instance;
  let closed = false,
    restored = false,
    anchor = /** @type {Wire|null} */ (null),
    origin = /** @type {Wire|null} */ (null);
  const rows = node("div"),
    controls = node("div");
  rows.className = "inbox-rows sy-row-list";
  controls.className = "inbox-read-controls sy-panel-body";
  const preview = node("section");
  preview.className = "inbox-preview sy-panel";
  preview.setAttribute(
    "aria-label",
    session === null ? "会话列表" : "会话只读预览",
  );
  root.append(preview);
  const seen = new Set();
  const heading = node("h2", session === null ? "最近会话" : `会话 ${session}`);
  heading.className = "sy-list-header";
  preview.append(heading);
  const actions = node("div");
  actions.className = "inbox-actions sy-panel-body";
  const createButton = node("button", "新建会话并打开主对话");
  createButton.className = "sy-button-accent";
  const createReason = node("p"),
    continueReason = node("p"),
    restoreNotice = node("p");
  for (const status of [createReason, continueReason, restoreNotice])
    status.setAttribute("role", "status");
  const continueButton = node("button", "继续此会话");
  continueButton.className = "sy-button-accent";
  let targetVerified = false,
    targetFailure = "",
    actionFailure = "";
  function paintActions() {
    const createState = dashboard.sessionActionState("create");
    createButton.disabled = !createState.allowed;
    createReason.textContent = createState.reason || actionFailure;
    for (const row of rows.querySelectorAll('[data-source-key="session"]')) {
      if (row instanceof HTMLElement)
        row.dataset.selected = String(
          row.dataset.sourceHighlighted === "true" ||
            row.dataset.sourceId === dashboard.runtime().session,
        );
    }
    if (session !== null) {
      const state = dashboard.sessionActionState("continue", session);
      const reason =
        state.reason ||
        (dashboard.runtime().instance !== connection
          ? "来源进程已变化，请重新核验会话。"
          : !targetVerified
            ? targetFailure || "正在核验会话身份，请等待读取。"
            : "");
      continueButton.disabled = !!reason;
      continueReason.textContent = reason;
    }
  }
  createButton.addEventListener("click", async () => {
    actionFailure = "";
    const result = await dashboard.createSession();
    if (closed) return;
    actionFailure = result.status === "applied" ? "" : result.reason;
    paintActions();
  });
  actions.append(createButton, createReason);
  preview.append(actions, restoreNotice);
  const back = node("a", "返回会话列表");
  back.href = "/inbox";
  if (session !== null) {
    follow(
      back,
      () =>
        void dashboard.navigate("/inbox", {
          source: origin || {
            route: "/inbox",
            kind: "sessions",
            anchor: session,
            trigger: {
              key: "open-session",
              href:
                "/inbox?" +
                new URLSearchParams({ session_id: session, view: "messages" }),
            },
            process_instance_id: connection,
          },
        }),
    );
    continueButton.addEventListener("click", async () => {
      const result = await dashboard.continueSession(session);
      if (closed) return;
      paintActions();
      if (result.status !== "applied")
        continueReason.textContent = result.reason;
    });
    const context = node("div");
    context.className = "inbox-context sy-panel-body";
    context.append(
      back,
      node("p", "只读预览；继续此会话将切换主对话。"),
      continueButton,
      continueReason,
    );
    const nav = node("nav");
    nav.className = "inbox-partitions sy-row-list";
    nav.setAttribute("aria-label", "会话预览分区");
    for (const [value, label] of [
      ["messages", "消息"],
      ["runs", "运行"],
    ]) {
      const link = node("a", label);
      link.className = "inbox-partition sy-row";
      link.href =
        "/inbox?" + new URLSearchParams({ session_id: session, view: value });
      if (value === partition) link.setAttribute("aria-current", "page");
      follow(
        link,
        () =>
          void dashboard.navigate(link.href, {
            source: { returnSource: origin },
          }),
      );
      nav.append(link);
    }
    preview.append(context, nav);
  }
  if (session !== null && !["messages", "runs"].includes(partition)) {
    targetFailure = "无效的会话预览分区。";
    const stopActions = dashboard.subscribeSessionActions(paintActions);
    preview.append(node("p", "无效的会话预览分区。"));
    return {
      close() {
        closed = true;
        stopActions();
      },
    };
  }
  preview.append(rows, controls);
  const kind =
    session === null
      ? "sessions"
      : partition === "messages"
        ? "messages"
        : "session-runs";
  const path =
    session === null
      ? "/api/sessions"
      : partition === "messages"
        ? "/api/sessions/messages"
        : "/api/sessions/runs";
  const params =
    session === null
      ? { limit: "25" }
      : partition === "messages"
        ? { session_id: session, page_size: "25" }
        : { session_id: session, limit: "25" };
  const label =
    session === null
      ? "会话"
      : partition === "messages"
        ? "会话消息"
        : "会话运行";
  /** SourceContext contains identifiers and presentation state only. */
  function captureSource() {
    return {
      route: url.pathname + url.search,
      kind,
      session_id: session,
      partition,
      anchor: anchor?.id ?? null,
      anchorKind: anchor?.kind ?? null,
      trigger: anchor?.trigger ?? null,
      process_instance_id: connection,
      observed_at: reader.observed,
      returnSource: origin,
    };
  }
  /** @param {HTMLAnchorElement} link @param {string} id @param {string} key */
  function open(link, id, key) {
    link.dataset.sourceTrigger =
      key === "session" ? "open-session" : "open-run";
    follow(link, () => {
      anchor = {
        id,
        kind: key,
        trigger: {
          key: link.dataset.sourceTrigger,
          href: link.getAttribute("href"),
        },
      };
      void dashboard.navigate(link.href, {
        source: { returnSource: captureSource() },
      });
    });
  }
  const reader = sourceReader(
    controls,
    path,
    params,
    (body, replace) => {
      const items =
        session === null
          ? [
              ...(body.non_terminal ? [body.non_terminal] : []),
              ...body.sessions,
            ]
          : partition === "messages"
            ? body.messages
            : body.runs;
      if (
        !Array.isArray(items) ||
        items.some(
          (item) =>
            typeof (session === null
              ? item.session_id
              : partition === "messages"
                ? item.message_anchor
                : item.run_id) !== "string",
        )
      )
        throw new Error("source_identity_missing");
      if (replace) {
        rows.replaceChildren();
        seen.clear();
      }
      if (typeof body.title === "string") heading.textContent = body.title;
      for (const item of items) {
        const id =
          session === null
            ? item.session_id
            : partition === "messages"
              ? item.message_anchor
              : item.run_id;
        if (seen.has(id)) continue;
        seen.add(id);
        let row = node("article");
        row.className = "inbox-row sy-row";
        row.dataset.sourceKey =
          session === null
            ? "session"
            : partition === "messages"
              ? "message"
              : "run";
        row.dataset.sourceId = id;
        const content = node("div");
        content.className = "sy-row-content";
        if (session === null) {
          row.dataset.selected = String(
            item.session_id === dashboard.runtime().session,
          );
          const link = node("a", item.title || "未命名会话");
          link.className = "inbox-session-title";
          link.href =
            "/inbox?" +
            new URLSearchParams({
              session_id: item.session_id,
              view: "messages",
            });
          open(link, id, "session");
          const metadata = node("div");
          metadata.className = "sy-row-meta inbox-session-meta";
          metadata.append(
            node("p", item.session_id),
            node("p", item.created_at),
          );
          content.append(link);
          row.append(content, metadata);
        } else if (partition === "messages") {
          const metadata = node(
            "p",
            `${item.role} · ${item.source} · ${item.created_at}`,
          );
          metadata.className = "sy-row-meta inbox-message-meta";
          clampedText(content, textBlocks(item.blocks), id);
          row.append(content, metadata);
          if (typeof item.run_id === "string") {
            const link = node("a", "查看运行");
            link.href =
              "/runs/" + encodeURIComponent(item.run_id) + "?filter=chat";
            open(link, id, "message");
            row.append(link);
          } else row.append(node("small", "历史消息 · 无 Run 关联"));
        } else {
          row = runRow(item);
          row.classList.add("inbox-row", "sy-row");
          const fields = row.querySelector(".run-fields");
          if (fields) {
            fields.classList.add("sy-row-meta", "inbox-run-meta");
            for (const field of fields.children) {
              if (field.querySelector("dt")?.textContent === "输入预览") {
                const prompt = node("dl");
                prompt.className = "inbox-run-preview";
                prompt.append(field);
                content.append(prompt);
                break;
              }
            }
          }
          if (typeof item.reply_preview === "string")
            clampedText(content, item.reply_preview, "reply-" + item.run_id);
          row.prepend(content);
          const link = node("a", "查看运行");
          link.href =
            "/runs/" + encodeURIComponent(item.run_id) + "?filter=chat";
          open(link, id, "run");
          row.append(link);
        }
        rows.append(row);
      }
      if (!seen.size && !body.runs_pending)
        rows.append(
          node(
            "p",
            session === null
              ? "还没有会话，可使用页头的新建会话入口。"
              : "此分区暂无已读记录。",
          ),
        );
      if (
        body.target &&
        body.target.placement !== "waiting" &&
        body.source_focus_allowed
      )
        queueMicrotask(() => {
          if (!closed) {
            const focused = highlightSource(
              rows,
              body.target.anchor,
              session === null
                ? "session"
                : partition === "messages"
                  ? "message"
                  : "run",
              anchor?.trigger || null,
              heading,
            );
            const selected = rows.querySelector(
              '[data-source-highlighted="true"]',
            );
            if (selected instanceof HTMLElement)
              selected.dataset.selected = "true";
            restoreNotice.textContent = focused
              ? "已重新核验来源并恢复原入口。"
              : "原入口已不可用，已恢复列表标题。";
          }
        });
    },
    label,
    dashboard.runtime,
    () => {
      targetVerified = true;
      targetFailure = "";
      paintActions();
      reconcileWaiting(dashboard.runtime());
    },
    (code) => {
      if (code === "unknown_session") {
        targetVerified = false;
        targetFailure = "此会话不存在或不可用，请返回会话列表。";
      } else if (!targetVerified)
        targetFailure = "会话身份尚未核验，请重试读取。";
      paintActions();
    },
  );
  let creationRevision = dashboard.sessionActionState("create").createdRevision;
  const stopActions = dashboard.subscribeSessionActions(() => {
    paintActions();
    const next = dashboard.sessionActionState("create").createdRevision;
    if (next > creationRevision && session === null)
      reader.changed("有新数据，请刷新会话。");
    creationRevision = next;
  });
  let lastRevision = dashboard.runtime().revision,
    lastActive = dashboard.runtime().active;
  /** Keep historical membership and cursors fixed; only announce related
   * durable-window changes observed through the accepted Host revisions.
   * @param {Wire} state */
  function observeChanges(state) {
    if (
      state.instance !== connection ||
      state.connected !== true ||
      !Number.isSafeInteger(state.revision)
    )
      return;
    if (state.revision > lastRevision) {
      const next = state.active;
      const related = (/** @type {Wire|null} */ run) =>
        typeof run?.session_id === "string" &&
        (session === null || run.session_id === session);
      const signature = (/** @type {Wire|null} */ run) =>
        run
          ? JSON.stringify([
              run.run_id,
              run.session_id,
              run.phase,
              run.recording_state,
            ])
          : "";
      const changed = signature(next) !== signature(lastActive);
      const settled =
        (related(next) &&
          ["recorded", "failed"].includes(next.recording_state)) ||
        (related(lastActive) && next?.run_id !== lastActive.run_id);
      // Absolute replacements may skip the active slot entirely. That revision
      // cannot prove this read unchanged, so offer a conservative explicit check.
      const unlocatedChange = !lastActive && !next && lastRevision >= 0;
      if (
        (changed &&
          (session === null
            ? related(next) || related(lastActive)
            : settled)) ||
        unlocatedChange
      )
        reader.changed(
          partition === "runs" && session !== null
            ? "有新运行，请刷新会话运行。"
            : "有新数据，请刷新" + label + "。",
        );
      lastRevision = state.revision;
      lastActive = next;
    }
  }
  /** A newer synchronized Host state can release this Session's waiting
   * boundary without reading or replacing its retained cursor.
   * @param {Wire} state */
  function reconcileWaiting(state) {
    if (
      session === null ||
      partition !== "messages" ||
      state.instance !== connection ||
      state.connected !== true
    )
      return;
    const active = state.active;
    if (
      active === null ||
      (active &&
        (active.session_id !== session ||
          ["recorded", "failed"].includes(active.recording_state)))
    )
      reader.releaseWaiting(state.revision);
  }
  let lastInstance = dashboard.runtime().instance,
    lastGap = 0;
  const unsubscribe = dashboard.subscribeState((/** @type {Wire} */ state) => {
    if (state.instance && state.instance !== lastInstance) {
      lastInstance = state.instance;
      reader.invalidate("进程已变化，请重新打开此页面");
    }
    if (state.connected === false) reader.invalidate("连接中断，保留旧快照");
    if (state.readGapRevision > lastGap) {
      lastGap = state.readGapRevision;
      reader.invalidate("增量通知缺口，快照待刷新");
    }
    observeChanges(state);
    reconcileWaiting(state);
    reader.sync();
  });
  queueMicrotask(() => {
    if (!closed && !restored) void reader.load();
  });
  return {
    captureSource,
    restoreSource(/** @type {Wire} */ source) {
      origin = source?.returnSource || null;
      if (source?.kind !== kind || typeof source.anchor !== "string") return;
      restored = true;
      anchor = {
        id: source.anchor,
        kind: source.anchorKind,
        trigger: source.trigger || null,
      };
      if (source.process_instance_id !== dashboard.runtime().instance) {
        reader.invalidate("来源进程已变化；请明确刷新当前列表");
        return;
      }
      const locate =
        session === null
          ? {
              path: "/api/sessions/locate",
              params: { session_id: source.anchor, limit: "25" },
            }
          : partition === "messages"
            ? {
                path: "/api/sessions/messages/locate",
                params: {
                  session_id: session,
                  anchor: source.anchor,
                  page_size: "25",
                },
              }
            : {
                path: "/api/sessions/runs/locate",
                params: {
                  session_id: session,
                  run_id: source.anchor,
                  limit: "25",
                },
              };
      void reader.load(true, locate);
    },
    close() {
      closed = true;
      reader.close();
      unsubscribe();
      stopActions();
    },
  };
}

before-inbox-runs.css.content:
.run-source,
.inbox-rows,
[aria-label="运行摘要"] {
  container-type: inline-size;
  min-width: 0;
}
.run-row {
  border: 1px solid var(--row-divider);
  border-radius: var(--radius-panel);
  margin-block: 12px;
  padding: 14px;
  min-width: 0;
  overflow-wrap: anywhere;
}
.run-fields {
  display: grid;
  gap: 12px;
  margin: 0 0 12px;
  grid-template-columns: minmax(0, 1fr);
}
.run-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-block: 12px;
}
.inbox-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-block: 12px;
}
.inbox-actions [role="status"] {
  flex-basis: 100%;
  margin: 0;
}
.inbox-actions [role="status"]:empty {
  display: none;
}
.run-fields > div {
  min-width: 0;
}
.run-fields dt {
  font-size: var(--font-size-meta);
  font-family: var(--font-mono);
  color: var(--metadata);
}
.run-fields dd {
  margin: 4px 0 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.run-table {
  display: block;
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.run-table thead {
  display: none;
}
.run-table tbody,
.run-table tr,
.run-table td {
  display: block;
  min-width: 0;
}
.run-table tr {
  border: 1px solid var(--row-divider);
  border-radius: var(--radius-console);
  padding: 12px;
  margin-block: 12px;
}
.run-table td {
  padding: 6px;
  overflow-wrap: anywhere;
  white-space: normal;
}
.run-table dl {
  margin: 0;
}
.run-table dt {
  font-size: var(--font-size-meta);
  font-family: var(--font-mono);
  color: var(--metadata);
}
.run-table dd {
  margin: 2px 0 7px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.run-preview {
  line-height: 1.5;
  max-height: 3em;
  overflow: hidden;
}
.run-preview.expanded {
  max-height: none;
}
@container (min-width:680px) {
  .run-fields {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .run-table {
    display: table;
  }
  .run-table thead {
    display: table-header-group;
  }
  .run-table tbody {
    display: table-row-group;
  }
  .run-table tr {
    display: table-row;
  }
  .run-table td,
  .run-table th {
    display: table-cell;
    vertical-align: top;
    border-bottom: 1px solid var(--row-divider);
    padding: 8px 6px;
  }
  .run-table th {
    font-size: var(--font-size-table-header);
    font-family: var(--font-mono);
    text-align: left;
  }
  .run-table th:first-child {
    width: 20%;
  }
  .run-table th:nth-child(2) {
    width: 19%;
  }
}
[data-source-highlighted="true"] {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
.evidence-text {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  max-width: 100%;
  line-height: 1.5;
  max-height: 9em;
  overflow: hidden;
  margin-block: 10px;
}
.evidence-text.expanded {
  max-height: none;
}
[aria-label="会话预览分区"] {
  display: flex;
  gap: 20px;
  margin-block: 16px;
}
[aria-label="会话预览分区"] [aria-current="page"] {
  font-weight: 700;
  text-decoration-thickness: 3px;
}
[aria-label="运行过程"] pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-width: 100%;
}

/* V05: all additions are scoped to the Run page; Inbox keeps its renderer. */
.runs-page {
  --run-line: calc(var(--gap-small) / 12);
  --run-body-y: calc(var(--gap-large) + var(--run-line));
  --run-body-x: calc(var(--gap-large) + var(--run-line) * 3);
}
.runs-page .run-table thead {
  display: none;
}
.runs-page .run-table tbody {
  display: block;
}
.runs-page .run-table .run-list-row {
  display: flex;
  align-items: baseline;
  border: 0;
  border-bottom: var(--run-line) solid var(--row-divider);
  border-radius: 0;
  margin: 0;
  padding: calc(var(--gap-small) - var(--run-line)) var(--gap-large);
}
.runs-page .run-table .run-list-row:last-child {
  border-bottom: 0;
}
